import {RANKS,getProgress,getMilestones,weeklyStats,validateRun,validateBackup,runXP,formatDuration,formatPace} from './engine.mjs';
import {RunTracker,parseGPX} from './tracker.mjs';

const KEY='runrank.data.v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',activity:'M3 12h4l3-8 4 16 3-8h4',flag:'M5 21V4m0 0c5-5 9 5 14 0v10c-5 5-9-5-14 0',trophy:'M8 3h8v7a4 4 0 0 1-8 0V3Zm8 2h4v3a5 5 0 0 1-5 5M8 5H4v3a5 5 0 0 0 5 5m3 1v5m-4 2h8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-5h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3 3-3',plus:'M12 5v14M5 12h14',arrow:'M4 12h15m-6-6 6 6-6 6',up:'m6 17 12-12M6 5h12v12',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',play:'m8 4 13 8-13 8Z',pause:'M8 4v16M16 4v16',stop:'M6 6h12v12H6Z',route:'M5 18a2 2 0 1 0 0 .01M19 4a2 2 0 1 0 0 .01M7 18h7a5 5 0 0 0 0-10h-4a3 3 0 0 1 0-6h7',clock:'M12 8v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',bolt:'m13 2-9 12h7l-1 8 10-13h-8z',leaf:'M20 3c-15-3-20 14-8 16 8 1 8-9 8-16M5 21 16 9',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Zm-4 9 3 3 5-5',lock:'M6 11h12v10H6ZM8 11V6a4 4 0 0 1 8 0v5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',phone:'M7 2h10a1 1 0 0 1 1 1v18a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1m3 16h4',check:'m5 12 4 4L20 5',info:'M12 11v6m0-10v.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',mountain:'m2 20 8-15 5 9 3-6 5 12ZM7 11l3 2 3-2',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',calendar:'M4 5h16v16H4ZM4 10h16M8 3v4m8-4v4',trash:'M3 6h18M9 3h6l1 3H8Zm-3 3 1 14h12l1-14M10 10v7m4-7v7',edit:'m4 16 12-12 4 4L8 20H4Zm10-10 4 4',heart:'M12 21 3 12C-2 4 8-1 12 6c4-7 14-2 9 6Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.spark}"/></svg>`;
const brand=()=>`<div class="brand"><div class="brand-mark">${icon('bolt')}</div><span>RUN<em>RANK</em></span></div>`;
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fmtDate=(d,opts={month:'short',day:'numeric'})=>new Date(d).toLocaleDateString(undefined,opts);
const km=n=>Number(n).toFixed(n>99?0:1);
const uid=()=>crypto.randomUUID?.()||`run-${Date.now()}-${Math.random().toString(16).slice(2)}`;
let data={version:1,profile:{name:'Runner',weeklyGoal:10},runs:[]},storageError='',storageSnapshot=null,view='home',historyFilter='all',query='',modalType='',modalDraft=null,importBackup=null,returnFocus=null;
try{const raw=localStorage.getItem(KEY);storageSnapshot=raw;if(raw)data=validateBackup(JSON.parse(raw));}catch{storageError='Your saved data could not be opened. Export a recovery copy in Settings before restoring a backup. Your existing data has not been changed.'}
function commit(next,{recover=false}={}){if(storageError&&!recover)throw Error('Your existing data needs recovery. Open Settings before saving.');const clean=validateBackup(next);try{if(!recover&&localStorage.getItem(KEY)!==storageSnapshot)throw Error('conflict');const serialized=JSON.stringify(clean);localStorage.setItem(KEY,serialized);storageSnapshot=serialized;}catch(error){if(error.message==='conflict')throw Error('Your history changed in another tab. Reload this app before saving to protect both copies.');throw Error('This device could not save your data. Free up browser storage or export a backup before trying again.');}data=clean;storageError='';}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500)}
const tracker=new RunTracker({onUpdate:state=>updateRecorder(state),onNotice:message=>toast(message)});
function crest(){return `<svg class="crest" viewBox="0 0 100 112" aria-hidden="true"><path d="M50 3 92 25v52L50 107 8 77V25Z" fill="#d5f875" stroke="#95a976" stroke-width="1.3"/><path d="m50 13 33 18v41l-33 24-33-24V31Z" fill="none" stroke="#a7ba83"/><path d="m28 68 22-35 23 35H59L50 53l-9 15Z" fill="#263d29"/><path d="m41 77 9-6 9 6-9 6Z" fill="#263d29"/><path d="M43 24h14" stroke="#263d29" stroke-width="2"/></svg>`}
function landscape(){let lines='';for(let i=0;i<14;i++)lines+=`<ellipse class="contour" cx="${225+i*2}" cy="${145+i*3}" rx="${33+i*17}" ry="${48+i*20}" transform="rotate(-30 225 145)"/>`;return `<svg class="hero-art" viewBox="0 0 330 350" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${lines}<path d="M69 318C64 264 203 276 188 226S72 231 100 176s130 2 116-54S150 87 185 47" fill="none" stroke="#d5f875" stroke-width="3.5" stroke-linecap="round"/><circle cx="69" cy="318" r="8" fill="#17251f" stroke="#d5f875" stroke-width="3"/><circle cx="185" cy="47" r="21" fill="#d5f875" opacity=".1"/><circle cx="185" cy="47" r="13" fill="#d5f875" opacity=".15"/><circle cx="185" cy="47" r="5" fill="#d5f875"/><g transform="translate(213 155)"><rect x="0" y="0" width="72" height="27" rx="7" fill="#304632" stroke="#678255" stroke-width=".6"/><text x="36" y="17" text-anchor="middle" fill="#d5f875" font-size="8" font-family="sans-serif" letter-spacing="1">YOUR PATH</text></g></svg>`}
const navItems=[['home','home','Overview'],['history','activity','My runs'],['milestones','trophy','Milestones'],['settings','settings','Settings']];
function nav(mobile=false){if(mobile)return `<nav class="mobile-nav" aria-label="Main navigation">${navItems.map(([id,ic,label],i)=>`${i===2?`<button class="record-tab" data-action="record" aria-label="Record a run"><span class="record-disc">${icon('plus')}</span><span>Record</span></button>`:''}<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label==='Overview'?'Home':label}</span></button>`).join('')}</nav>`;return `<nav class="nav" aria-label="Main navigation">${navItems.map(([id,ic,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav>`}
function render(){const p=getProgress(data.runs);const state=tracker.snapshot();$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="eyebrow">Your running world</div>${nav()}<div class="side-bottom"><div class="solo-card">${icon('leaf')}<strong>A little further, together.</strong><p>Just you and your next milestone. Every pace belongs here.</p></div><button class="profile-button" data-view="settings"><span class="avatar">${esc(data.profile.name.slice(0,2).toUpperCase())}</span><span><strong>${esc(data.profile.name)}</strong><small>Level ${p.level} · ${p.rank}</small></span>${icon('chevron')}</button></div></aside><main class="main"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="breadcrumb">Your space <span>/</span> <span>${navItems.find(x=>x[0]===view)?.[2]||'Overview'}</span></div><div class="top-actions"><time>${fmtDate(new Date(),{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</time><span class="private-label">${icon('lock')} Personal space</span><button class="icon-btn" data-action="install" aria-label="Add to iPhone home screen">${icon('phone')}</button></div></header>${storageError?`<div class="notice-banner">${icon('info')}<span>${esc(storageError)}</span><button class="btn btn-secondary" data-view="settings">Settings</button></div>`:''}${state.status!=='idle'?`<div class="notice-banner">${icon('activity')}<span>Your run is ${state.status==='paused'?'paused':state.status==='acquiring'?'waiting for GPS':'recording'}. ${state.status==='paused'?'Open the recorder to resume or save.':'Keep this app open while running.'}</span><button class="btn btn-primary" data-action="record">Open recorder</button></div>`:''}${view==='home'?home():view==='history'?history():view==='milestones'?milestones():settings()}<footer class="footer"><span>${icon('leaf')} Built for the long run. One step at a time.</span><span>${icon('lock')} Saved on this device · Your personal journey</span></footer></main>${nav(true)}</div>`;}
function sectionHead(eyebrow,title,copy,action=true){return `<section class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div>${action?`<button class="btn btn-secondary" data-action="manual">${icon('plus')} Add a run</button>`:''}</section>`}
function stat(label,value,unit,foot,ic){return `<div class="stat"><div class="stat-top"><span>${label}</span>${icon(ic)}</div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-foot">${foot}</div></div>`}
function home(){const p=getProgress(data.runs),w=weeklyStats(data.runs),ms=getMilestones(data.runs),nextRank=RANKS.find(r=>r.xp>p.totalXP),unlocked=ms.filter(m=>m.unlocked).length;const missions=ms.filter(m=>!m.unlocked).slice(0,3);return `${sectionHead('YOUR PERSONAL RUNNING CLUB',`Your pace. <em>Your progress.</em>`,data.runs.length?`Welcome back, ${esc(data.profile.name)}. Let’s keep your story moving.`:'A fresh start. A path of your own. Let’s see where it goes.')}<div class="hero-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> THE NEXT CHAPTER IS YOURS</div><h2>Small steps.<br><span>Real progress.</span></h2><p>Every run adds to your story.<br>Head outside. Come back a little further.</p><button class="btn btn-lime" data-action="record">${icon('play')} ${tracker.snapshot().status==='idle'?'Start a run':'Open your run'} ${icon('arrow')}</button></div>${landscape()}<div class="hero-stamp">${icon('mountain')} MADE FOR YOUR PACE</div></section><section class="rank-card"><div class="rank-card-top"><span class="card-label">Your game rank</span><span class="mini-pill">LEVEL ${p.level.toString().padStart(2,'0')}</span></div><div class="rank-center">${crest()}<div><h2>${p.rank}</h2><p>${p.totalXP.toLocaleString()} XP earned${p.totalRuns?' · Keep it going':' · Your journey begins'}</p></div></div><div class="progress-label"><strong>Next level</strong><span>${p.levelXP} / ${p.nextLevelXP} XP</span></div><div class="progress-bar" role="progressbar" aria-label="Next level experience" aria-valuenow="${p.levelXP}" aria-valuemin="0" aria-valuemax="500"><div class="progress-fill" style="width:${p.progressPct}%"></div></div><div class="rank-foot">${icon('spark')} ${nextRank?`${nextRank.xp-p.totalXP} XP to ${nextRank.name}`:'Legend unlocked. Your story keeps going.'}</div></section></div><div class="stat-grid">${stat('Total distance',km(p.totalKm),'km',p.totalRuns?'Every kilometre counts':'Your first kilometre is ahead','route')}${stat('Runs completed',p.totalRuns,'runs',p.totalRuns?'Showing up is progress':'Your starting line is here','flag')}${stat('Time on your feet',Math.floor(p.totalSeconds/3600),'h '+Math.floor(p.totalSeconds%3600/60)+'m','Time well spent outside','clock')}${stat('Milestones earned',unlocked,`/ ${ms.length}`,unlocked?'Look how far you’ve come':'Your first badge is waiting','trophy')}</div><div class="content-grid"><div><section class="panel"><div class="panel-head"><div><h2>This week, in motion</h2><div class="sub">Little by little adds up.</div></div><span class="small-chip">${fmtDate(w.days[0].date+'T12:00:00')} – ${fmtDate(w.days[6].date+'T12:00:00')}</span></div><div class="week-top"><strong>${km(w.distanceKm)}</strong><span>/ ${data.profile.weeklyGoal} km weekly goal</span></div>${chart(w)}<p class="chart-note">${icon('leaf')}${w.distanceKm>=data.profile.weeklyGoal?'Weekly goal complete. Make room for recovery, too.':`${km(Math.max(0,data.profile.weeklyGoal-w.distanceKm))} km to your weekly goal. Your pace, your schedule.`}</p></section><section class="panel"><div class="panel-head"><h2>Your latest runs</h2><button class="btn btn-link" data-view="history">View all ${icon('arrow')}</button></div>${data.runs.length?sortedRuns().slice(0,3).map(activityRow).join(''):`<div class="empty-activity"><div class="empty-route">${icon('route')}</div><div><h3>Every story has a first run.</h3><p>Record a run or add one you’ve already completed. Your journey will show up here.</p><button class="btn btn-link" data-action="manual">Add your first run ${icon('arrow')}</button></div></div>`}</section></div><div><section class="panel"><div class="panel-head"><h2>Your next milestones</h2><span class="small-chip">${ms.length-unlocked} to discover</span></div>${missions.length?missions.map((m,i)=>quest(m,i)).join(''):`<div class="empty-activity"><div><h3>You’ve earned every milestone.</h3><p>Keep adding runs to grow your level. Take a moment to enjoy how far you’ve come.</p></div></div>`}</section><section class="outro">${icon('heart')}<h3>Progress isn’t always<br>a faster pace.</h3><p>Sometimes, it’s simply showing up.<br>Your effort counts. Rest days belong, too.</p></section></div></div>`}
function chart(w){const max=Math.max(...w.days.map(d=>d.km),1),today=dateKey();return `<div class="chart" role="img" aria-label="Distance this week: ${w.days.map(d=>`${d.date}: ${km(d.km)} km`).join(', ')}">${w.days.map(d=>`<div class="bar-col"><div class="bar ${d.date===today?'today':''}" style="height:${Math.max(d.km/max*88,3)}%">${d.km?`<span class="bar-label">${km(d.km)}</span>`:''}</div></div>`).join('')}</div><div class="day-row">${w.days.map(d=>`<span class="${d.date===today?'today':''}">${d.label}</span>`).join('')}</div>`}
function quest(m,i){return `<div class="quest ${m.unlocked?'done':''}"><div class="quest-icon">${icon(['flag','route','mountain'][i%3])}</div><div class="quest-body"><h3>${m.title}</h3><p>${m.description}</p><div class="progress-bar"><div class="progress-fill" style="width:${Math.min(m.value/m.target*100,100)}%"></div></div><div class="quest-bottom"><span>${m.unit==='km'?km(Math.min(m.value,m.target)):Math.min(m.value,m.target)} / ${m.target} ${m.unit}</span><span>Badge reward</span></div></div></div>`}
function sortedRuns(){return [...data.runs].sort((a,b)=>new Date(b.date)-new Date(a.date))}
function activityRow(r){return `<button class="activity-row" data-detail="${esc(r.id)}"><span class="activity-icon">${icon(r.source==='manual'?'flag':'route')}</span><span class="activity-info"><h3>${esc(r.title)}</h3><p>${fmtDate(r.date)} · ${formatDuration(r.durationSec)} · ${formatPace(r.durationSec,r.distanceKm)} /km</p></span><span class="activity-distance"><strong>${km(r.distanceKm)} <span class="subtle">km</span></strong><small>+${runXP(r)} XP</small></span>${icon('chevron')}</button>`}
function filteredRuns(){return sortedRuns().filter(r=>(historyFilter==='all'||r.source===historyFilter)&&`${r.title} ${r.notes}`.toLowerCase().includes(query.toLowerCase()))}
function historyList(){const runs=filteredRuns();return runs.length?runs.map(activityRow).join(''):`<div class="empty-large"><div class="badge-icon">${icon('route')}</div><h2>${data.runs.length?'No runs found':'Your running story starts here.'}</h2><p>${data.runs.length?'Try a different search or recording type.':'Capture your next run, add a past one, or import a GPX file from your running app.'}</p>${data.runs.length?'':`<button class="btn btn-primary" data-action="manual">${icon('plus')} Add your first run</button>`}</div>`}
function history(){return `${sectionHead('THE STEPS YOU’VE TAKEN','Your running story.','A record of your effort, at every pace.')}<div class="history-tools"><div class="search">${icon('search')}<input id="history-search" type="search" placeholder="Find a run…" aria-label="Search your runs" value="${esc(query)}"></div><div class="filters" aria-label="Filter runs">${[['all','All runs'],['gps','GPS'],['manual','Manual'],['gpx','Imported']].map(([id,label])=>`<button data-filter="${id}" class="${historyFilter===id?'active':''}" aria-pressed="${historyFilter===id}">${label}</button>`).join('')}</div></div><section class="panel"><div class="panel-head"><h2>${data.runs.length} saved ${data.runs.length===1?'run':'runs'}</h2><button class="btn btn-link" data-action="import-gpx">${icon('upload')} Import GPX</button></div><div id="history-list">${historyList()}</div></section><div class="explain">${icon('info')}<p>Your runs stay in this browser on this device. Export a backup in Settings to keep a copy or move your history to another device.</p></div>`}
function milestones(){const p=getProgress(data.runs),ms=getMilestones(data.runs);return `${sectionHead('PROOF OF YOUR PROGRESS','Effort worth celebrating.','Build experience. Collect milestones. Follow your own path.',false)}<section class="panel"><div class="panel-head"><h2>The path ahead</h2><span class="small-chip">${p.totalXP.toLocaleString()} TOTAL XP</span></div><div class="rank-ladder">${RANKS.map((r,i)=>`<div class="ladder-rank ${p.totalXP>=r.xp?'achieved':''}"><div class="ladder-icon">${icon(['leaf','flag','route','mountain','shield','trophy'][i])}</div><strong>${r.name}</strong><small>${r.xp.toLocaleString()} XP</small></div>`).join('')}</div><p class="explain"><strong>How it works:</strong> Every saved run earns 50 XP, plus 100 XP per kilometre (rounded down to whole XP). Every 500 XP earns a level. Badges celebrate milestones; they don’t add extra XP. Your game rank reflects accumulated effort, not speed or placement against other runners.</p></section><div class="heading"><div><h2 style="font-size:20px;margin:0">Your milestone collection</h2><p>${ms.filter(m=>m.unlocked).length} of ${ms.length} unlocked. There’s no deadline.</p></div></div><div class="badge-grid">${ms.map((m,i)=>`<section class="badge-card ${m.unlocked?'unlocked':''}"><div class="badge-icon">${icon(m.unlocked?'check':['flag','leaf','route','mountain','shield','calendar','bolt','trophy'][i])}</div><h3>${m.title}</h3><p>${m.description}</p><div class="progress-label"><strong>${m.unlocked?'Unlocked':`${m.unit==='km'?km(Math.min(m.value,m.target)):Math.min(m.value,m.target)} / ${m.target} ${m.unit}`}</strong><span>${m.unlocked?'Yours to keep':'In progress'}</span></div><div class="progress-bar"><div class="progress-fill" style="width:${Math.min(100,m.value/m.target*100)}%"></div></div></section>`).join('')}</div>`}
function settings(){return `${sectionHead('MAKE IT YOURS','Your space. Your rules.','A simple setup for your personal running journey.',false)}<div class="settings-grid"><div><section class="panel"><div class="panel-head"><h2>Your runner profile</h2>${icon('leaf')}</div><form id="profile-form"><div class="form-field"><label for="runner-name">What should we call you?</label><input id="runner-name" name="name" maxlength="48" required value="${esc(data.profile.name)}" autocomplete="given-name"></div><div class="form-field"><label for="weekly-goal">Weekly distance goal · km</label><input id="weekly-goal" name="goal" type="number" inputmode="decimal" min="0.1" max="1000" step="0.1" required value="${data.profile.weeklyGoal}"><small>A guide, not a deadline. Choose what feels manageable for you.</small></div><div id="profile-error"></div><button class="btn btn-primary" type="submit">Save preferences ${icon('check')}</button></form></section><section class="panel"><div class="panel-head"><h2>Made for your iPhone</h2>${icon('phone')}</div><p class="settings-copy">Keep Run Rank a tap away on your home screen.</p><ol class="steps"><li>Open your Run Rank link in <strong>Safari</strong>.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</li><li>If shown, turn on <strong>Open as Web App</strong>, then tap <strong>Add</strong>.</li></ol><p class="settings-copy"><strong>While recording:</strong> keep Run Rank visible and your screen unlocked. Recording pauses when you switch apps or lock the screen. We request a screen wake lock when supported.</p><p class="settings-copy">The app can reopen offline after a successful online visit. Open it once online from the home-screen icon before relying on it offline.</p></section></div><div><section class="panel"><div class="panel-head"><h2>Your data, in your hands</h2>${icon('shield')}</div><p class="settings-copy">Runs, routes, and milestones are saved <strong>only in this browser on this device</strong>. There is no cloud sync. Clearing website data can remove your history.</p><div class="button-row"><button class="btn btn-primary" data-action="export">${icon('download')} Export backup</button><button class="btn btn-secondary" data-action="restore">${icon('upload')} Restore backup</button></div>${storageError?`<button class="btn btn-secondary full-width" data-action="recovery" style="margin-top:10px">Download original data for recovery</button>`:''}<hr class="settings-sep"><h2>Bring a run with you</h2><p class="settings-copy">Import a timed GPX route exported from Strava or another tracker. Review its distance and time before saving. There is no direct Strava account connection.</p><button class="btn btn-secondary" data-action="import-gpx">${icon('upload')} Import GPX file</button><p class="settings-copy">No GPS file? You can always add distance and time by hand.</p><button class="btn btn-link" data-action="manual">Add a completed run ${icon('arrow')}</button></section><section class="panel"><div class="panel-head"><h2>A game about your progress</h2>${icon('spark')}</div><p class="settings-copy">You earn XP for distance and completed runs. Your game rank is a personal achievement, not a global ranking. There are no public leaderboards or other runners’ profiles.</p><button class="btn btn-link" data-view="milestones">See progression rules ${icon('arrow')}</button></section></div></div>`}
function openModal(content,type){returnFocus=document.activeElement;modalType=type;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${content}</section></div>`;$('#app').inert=true;const focus=$('.modal input:not([readonly]),.modal button');focus?.focus();}
function closeModal(){modalType='';modalDraft=null;importBackup=null;$('#modal-root').innerHTML='';$('#app').inert=false;render();returnFocus?.isConnected?returnFocus.focus():$('.main button')?.focus();}
function modalHeader(title,copy,eyebrow='YOUR RUNNING JOURNEY'){return `<div class="modal-header"><div><div class="eyebrow subtle">${eyebrow}</div><h2 id="modal-title">${title}</h2><p>${esc(copy)}</p></div><button class="close-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`}
function manual(draft=null){modalDraft=draft;const d=draft||{};const locked=d.source&&d.source!=='manual';const duration=Math.round(d.durationSec||0);openModal(`${modalHeader(draft?'Review your run':'Add a run',locked?'Check your recorded activity before saving.':'A little effort today. A little more progress forever.')}<form id="run-form"><div id="run-error"></div><div class="form-field"><label for="run-title">Run name</label><input id="run-title" name="title" placeholder="e.g. An easy morning run" value="${esc(d.title||'')}" maxlength="100" required></div><div class="form-row"><div class="form-field"><label for="run-distance">Distance · km</label><input id="run-distance" name="distance" type="number" inputmode="decimal" min="0.001" max="1000" step="any" value="${d.distanceKm?Number(d.distanceKm.toFixed(3)):''}" ${locked?'readonly':''} placeholder="3.0" required></div><div class="form-field"><label for="run-date">Date</label><input id="run-date" name="date" type="date" max="${dateKey()}" value="${dateKey(d.date?new Date(d.date):new Date())}" required ${locked?'readonly':''}></div></div><div class="form-row"><div class="form-field"><label for="run-hours">Hours</label><input id="run-hours" name="hours" type="number" inputmode="numeric" min="0" max="168" value="${Math.floor(duration/3600)}" required ${locked?'readonly':''}></div><div class="form-field"><label for="run-minutes">Minutes</label><input id="run-minutes" name="minutes" type="number" inputmode="numeric" min="0" max="59" value="${draft?Math.floor(duration%3600/60):''}" placeholder="25" required ${locked?'readonly':''}></div><div class="form-field"><label for="run-seconds">Seconds</label><input id="run-seconds" name="seconds" type="number" inputmode="numeric" min="0" max="59" value="${duration%60}" required ${locked?'readonly':''}></div></div><div id="run-estimate" class="explain" style="margin-bottom:18px">50 XP for showing up + 100 XP per kilometre.</div>${locked?`<p class="source-note">${d.source==='gpx'?'GPX timing uses elapsed time within each track segment; pauses inside a segment are included.':'GPS timing excludes time paused in Run Rank.'} Your route is saved on this device.</p>`:''}<div class="form-field"><label for="run-notes">How did it feel? <span class="subtle">Optional</span></label><textarea id="run-notes" name="notes" rows="2" maxlength="2000" placeholder="Fresh air, good company, a new route…">${esc(d.notes||'')}</textarea></div><button class="btn btn-primary full-width" type="submit">Save run & earn XP ${icon('arrow')}</button><p class="modal-foot">Every pace counts. Rest days belong, too.</p></form>`,'manual');modalDraft=draft;updateEstimate();}
function updateEstimate(){if(!$('#run-form'))return;const f=new FormData($('#run-form')),distanceKm=modalDraft?.distanceKm||Number(f.get('distance')),durationSec=modalDraft?.durationSec||Number(f.get('hours'))*3600+Number(f.get('minutes'))*60+Number(f.get('seconds'));$('#run-estimate').innerHTML=distanceKm>0&&durationSec>0?`<strong>+${runXP({distanceKm,durationSec})} XP</strong> for your effort · Average pace <strong>${formatPace(durationSec,distanceKm)} /km</strong>`:'50 XP for showing up + 100 XP per kilometre.'}
function saveRun(form){const f=new FormData(form);try{const draft=modalDraft;const source=draft?.source||'manual';const run=validateRun({id:uid(),title:f.get('title'),date:draft?.date||f.get('date'),distanceKm:draft?.distanceKm||Number(f.get('distance')),durationSec:draft?.durationSec||Number(f.get('hours'))*3600+Number(f.get('minutes'))*60+Number(f.get('seconds')),notes:f.get('notes'),source,route:draft?.route||[]});if(new Date(run.date).getTime()>Date.now()+86400000)throw Error('Choose today or a past date.');if(source==='gpx'&&data.runs.some(r=>r.source==='gpx'&&r.date===run.date&&Math.abs(r.distanceKm-run.distanceKm)<.001&&Math.abs(r.durationSec-run.durationSec)<1))throw Error('This GPX run is already in your history.');const before=getMilestones(data.runs),beforeProgress=getProgress(data.runs);commit({...data,runs:[...data.runs,run]});if(source==='gps')tracker.discard();modalDraft=null;view='home';render();const earned=getMilestones(data.runs).filter(m=>m.unlocked&&!before.find(b=>b.id===m.id)?.unlocked);const progress=getProgress(data.runs);openModal(`<div class="success-head"><div class="badge-icon">${icon('check')}</div><div class="eyebrow subtle">RUN SAVED</div><h2 id="modal-title">That effort counts.</h2><p>${km(run.distanceKm)} km added to your story.<br>${progress.level>beforeProgress.level?`You reached Level ${progress.level}. Keep following your own path.`:'One more run. One more step on your own path.'}</p></div><div class="success-xp">+${runXP(run)} <small>XP earned</small></div>${earned.map(m=>`<div class="success-milestone">${icon('trophy')}<span><strong>${m.title}</strong><small>Milestone unlocked · ${m.description}</small></span></div>`).join('')}<button class="btn btn-primary full-width" data-action="close" style="margin-top:22px">See my progress ${icon('arrow')}</button>`,'success');}catch(e){$('#run-error').innerHTML=`<p class="form-error" role="alert">${esc(e.message)}</p>`}}
function record(){openModal(`${modalHeader('Your next run.','Go at a pace that feels like yours.','READY WHEN YOU ARE')}<div class="record-stage"><div id="gps-status" class="gps-status"></div><div id="record-distance" class="record-distance">0.00</div><div class="record-unit">kilometres</div><div class="record-metrics"><div><strong id="record-time">00:00</strong><small>Active time</small></div><div><strong id="record-pace">—</strong><small>Avg. pace /km</small></div></div></div><p class="rec-note"><b>On iPhone, keep this app open and the screen unlocked.</b> Switching apps or locking your phone pauses recording. GPS starts after you allow location access.</p><div id="rec-message" class="explain" style="margin-bottom:18px" role="status"></div><div id="rec-controls" class="record-buttons"></div><button class="btn btn-link full-width" data-action="manual">Prefer to add a completed run?</button>`,'record');updateRecorder(tracker.snapshot());}
function updateRecorder(s){if(modalType!=='record')return;$('#record-distance').textContent=s.distanceKm.toFixed(2);$('#record-time').textContent=formatDuration(s.durationSec);$('#record-pace').textContent=formatPace(s.durationSec,s.distanceKm);$('#gps-status').innerHTML=`<span class="status-dot"></span>${s.status==='idle'?'Ready to explore':s.status==='acquiring'?'Finding your location':s.status==='recording'?`GPS recording${s.accuracy?` · ±${s.accuracy} m`:''}`:'Run paused'}`;$('#gps-status').classList.toggle('warn',s.status==='paused');$('#rec-message').textContent=s.message;const controls=$('#rec-controls');if(controls.dataset.status!==s.status){controls.dataset.status=s.status;controls.innerHTML=s.status==='idle'?`<button class="btn btn-primary" data-action="start-gps">${icon('play')} Start recording</button>`:s.status==='recording'||s.status==='acquiring'?`<button class="btn btn-secondary" data-action="pause-gps">${icon('pause')} Pause</button><button class="btn btn-primary" data-action="finish-gps">${icon('stop')} Finish</button>`:`<button class="btn btn-secondary" data-action="resume-gps">${icon('play')} Resume</button><button class="btn btn-primary" data-action="finish-gps">${icon('check')} Finish</button><button class="btn btn-danger" data-action="discard-gps" aria-label="Discard this recording">${icon('trash')}</button>`}}
function finishGPS(){const s=tracker.finish();if(s.distanceKm<=0||s.durationSec<=0){toast('No running distance recorded yet. Resume outdoors, or discard this recording and add your run manually.');return;}manual({title:'My outdoor run',date:s.startedAt,distanceKm:s.distanceKm,durationSec:s.durationSec,source:'gps',route:s.route});}
function routePlot(route){if(!route.length)return '';const mean=route.reduce((a,p)=>a+p.lat,0)/route.length;const cos=Math.max(.001,Math.cos(mean*Math.PI/180));let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;for(const p of route){minX=Math.min(minX,p.lng*cos);maxX=Math.max(maxX,p.lng*cos);minY=Math.min(minY,p.lat);maxY=Math.max(maxY,p.lat)}const scale=Math.min(550/(maxX-minX||.00001),205/(maxY-minY||.00001));const x=p=>300+(p.lng*cos-(maxX+minX)/2)*scale,y=p=>130-(p.lat-(maxY+minY)/2)*scale;let parts=[],segment=null;const selected=route.filter((p,i)=>i%Math.max(1,Math.floor(route.length/1400))===0||i===route.length-1||i===0||p.segment!==route[i-1]?.segment);for(const p of selected){parts.push(`${p.segment!==segment?'M':'L'}${x(p).toFixed(1)},${y(p).toFixed(1)}`);segment=p.segment}const first=route[0],last=route.at(-1);return `<div class="route-plot"><svg viewBox="0 0 600 260" role="img" aria-label="Recorded route outline. This is not a street map."><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#dce4d2" stroke-width="1"/></pattern></defs><rect width="600" height="260" fill="url(#grid)"/><path d="${parts.join(' ')}" stroke="#668b3c" stroke-width="4" fill="none" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${x(first)}" cy="${y(first)}" r="6" fill="#e8ffc3" stroke="#668b3c" stroke-width="3"/><circle cx="${x(last)}" cy="${y(last)}" r="6" fill="#17251f"/></svg></div>`}
function detail(id){const r=data.runs.find(r=>r.id===id);if(!r)return;modalDraft=r;openModal(`${modalHeader(esc(r.title),`${fmtDate(r.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · +${runXP(r)} XP`,'ONE MORE STEP FORWARD')}${routePlot(r.route)}${r.route.length?'<p class="source-note">Your route outline · light circle = start · dark circle = finish</p>':''}<div class="detail-stats"><div><strong>${km(r.distanceKm)}</strong><span>kilometres</span></div><div><strong>${formatDuration(r.durationSec)}</strong><span>${r.source==='gpx'?'segment time':'duration'}</span></div><div><strong>${formatPace(r.durationSec,r.distanceKm)}</strong><span>pace /km</span></div></div><div class="activity-meta"><span>${r.source==='manual'?'Added manually':r.source==='gps'?'Recorded with GPS':'Imported from GPX'}</span><span>Saved on this device</span></div>${r.notes?`<p class="notes-text">${esc(r.notes)}</p>`:''}<div class="button-row">${r.route.length?`<button class="btn btn-secondary" data-export-gpx="${esc(r.id)}">${icon('download')} Export GPX</button>`:''}<button class="btn btn-danger" data-delete="${esc(r.id)}">${icon('trash')} Delete run</button></div>`,'detail');modalDraft=r;}
function confirmModal(title,copy,action,label){openModal(`${modalHeader(title,copy,'TAKE A MOMENT')}<div class="button-row"><button class="btn btn-secondary" data-action="close">Cancel</button><button class="btn btn-danger" data-action="${action}">${label}</button></div>`,'confirm');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function exportBackup(){download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`Run-Rank-backup-${dateKey()}.json`);toast('Backup prepared. On iPhone, save it to Files.');}
function exportGPX(id){const r=data.runs.find(r=>r.id===id);if(!r)return;let segments=[];let last;for(const p of r.route){if(p.segment!==last){segments.push([]);last=p.segment;}segments.at(-1).push(`<trkpt lat="${p.lat}" lon="${p.lng}"><time>${new Date(p.t).toISOString()}</time></trkpt>`)}const xml=`<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Run Rank" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>${esc(r.title)}</name>${segments.map(s=>`<trkseg>${s.join('')}</trkseg>`).join('')}</trk></gpx>`;download(new Blob([xml],{type:'application/gpx+xml'}),`Run-Rank-${dateKey(new Date(r.date))}.gpx`)}
function install(){openModal(`${modalHeader('Your run. One tap away.','Add Run Rank to your iPhone home screen.','RUN RANK ON IPHONE')}<div class="welcome-features"><div class="welcome-feature"><div class="quest-icon">${icon('phone')}</div><div><strong>1. Open in Safari</strong><p>Use your private Run Rank link and sign in if asked.</p></div></div><div class="welcome-feature"><div class="quest-icon">${icon('upload')}</div><div><strong>2. Share → Add to Home Screen</strong><p>Turn on Open as Web App if shown, then tap Add.</p></div></div><div class="welcome-feature"><div class="quest-icon">${icon('flag')}</div><div><strong>3. Open from your new icon</strong><p>Visit once online to prepare the app for offline use.</p></div></div></div><p class="explain">Keep the app visible and your screen unlocked during GPS recording. Runs stay on this device; use a backup to move them between browsers or devices.</p><button class="btn btn-primary full-width" data-action="close">Let’s get moving ${icon('arrow')}</button>`,'install');}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.view){if(modalType)closeModal();view=el.dataset.view;render();window.scrollTo({top:0,behavior:'instant'});return;}if(el.dataset.filter){historyFilter=el.dataset.filter;render();return;}if(el.dataset.detail){detail(el.dataset.detail);return;}if(el.dataset.exportGpx){exportGPX(el.dataset.exportGpx);return;}if(el.dataset.delete){const id=el.dataset.delete;confirmModal('Delete this run?','This removes its distance, XP, and route. Levels and milestones will be recalculated.','confirm-delete','Delete run');modalDraft={id};return;}switch(el.dataset.action){case'close':closeModal();break;case'manual':manual();break;case'record':record();break;case'start-gps':tracker.start();break;case'pause-gps':tracker.pause();break;case'resume-gps':tracker.resume();break;case'finish-gps':finishGPS();break;case'discard-gps':confirmModal('Discard this recording?','This unsaved route and timer will be removed. Your saved run history will stay intact.','confirm-discard','Discard recording');break;case'confirm-discard':tracker.discard();closeModal();toast('Recording discarded.');break;case'confirm-delete':try{commit({...data,runs:data.runs.filter(r=>r.id!==modalDraft.id)});closeModal();toast('Run deleted. Your progress has been updated.');}catch(e){toast(e.message)}break;case'install':install();break;case'export':exportBackup();break;case'restore':$('#backup-input').click();break;case'import-gpx':$('#gpx-input').click();break;case'confirm-restore':try{commit(importBackup,{recover:true});closeModal();toast('Backup restored. Your journey is ready.');}catch(e){toast(e.message)}break;case'recovery':try{download(new Blob([localStorage.getItem(KEY)||''],{type:'application/json'}),`Run-Rank-recovery-${dateKey()}.json`);}catch{toast('This browser is blocking access to saved data.');}break;}});
document.addEventListener('submit',e=>{if(e.target.id==='run-form'){e.preventDefault();saveRun(e.target)}if(e.target.id==='profile-form'){e.preventDefault();try{const f=new FormData(e.target);commit({...data,profile:{name:f.get('name'),weeklyGoal:Number(f.get('goal'))}});render();toast('Preferences saved. Make this journey yours.');}catch(err){$('#profile-error').innerHTML=`<p class="form-error" role="alert">${esc(err.message)}</p>`}}});
document.addEventListener('input',e=>{if(e.target.closest('#run-form'))updateEstimate();if(e.target.id==='history-search'){query=e.target.value;$('#history-list').innerHTML=historyList()}});
document.addEventListener('keydown',e=>{if(!modalType)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const items=[...document.querySelectorAll('.modal button:not([disabled]),.modal input,.modal textarea,.modal select')].filter(x=>x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#gpx-input').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Choose a GPX file smaller than 10 MB.');const run=parseGPX(await file.text());manual(run);}catch(err){toast(err.message)}});
$('#backup-input').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>40*1024*1024)throw Error('Choose a backup smaller than 40 MB.');const backup=validateBackup(JSON.parse(await file.text()));confirmModal('Restore this backup?',`This backup contains ${backup.runs.length} runs for ${backup.profile.name}. It will replace the ${data.runs.length} runs currently on this device. Export your current history first if you want to keep it.`,'confirm-restore','Replace & restore');importBackup=backup;}catch(err){toast(`Could not restore: ${err.message}`)}});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{if(e.newValue){data=validateBackup(JSON.parse(e.newValue));storageSnapshot=e.newValue;storageError='';if(!modalType)render();toast('Your history was updated in another tab.');}else{storageError='Saved data was removed in another tab. Reload before saving, or export a recovery copy.';if(!modalType)render();}}catch{storageError='Saved data changed in another tab but could not be read. Download a recovery copy in Settings before restoring a backup.';if(!modalType)render();toast(storageError);}});
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{console.info('Offline setup is not available in this browser.');});
